def line_totals_by_order(
    orders: list[list[tuple[int, int]]],
) -> list[list[int]]:
    """Compute each order's line totals in cents."""
    totals = []
    for order in orders:
        totals.append([quantity * price for quantity, price in order])
    return totals

def search_terms(lines: list[str]) -> list[str]:
    """Collect normalized words from multiple search-query lines."""
    terms = []
    for line in lines:
        terms.extend([word.lower() for word in line.split()])
    return terms

def recipient_addresses(
    primary: list[str], copied: list[str]
) -> list[str]:
    """Normalize recipients and add copied addresses once."""
    addresses = [address.strip().lower() for address in primary]
    destination = addresses
    for address in copied:
        normalized = address.strip().lower()
        if normalized not in destination:
            destination.append(normalized)
    return addresses

def _fahrenheit_batch(celsius: list[float]) -> list[float]:
    """Convert one batch while preserving its order."""
    converted = []
    for temperature in celsius:
        converted.append(temperature * 9.0 / 5.0 + 32.0)
    return converted


def convert_batches(batches: list[list[float]]) -> list[list[float]]:
    """Convert all sensor batches to Fahrenheit."""
    return [_fahrenheit_batch(batch) for batch in batches]

def normalize_tags(tags: list[str], unique: bool) -> list[str]:
    """Normalize tags, optionally keeping only their first occurrence."""
    if not unique:
        return [tag.strip().lower() for tag in tags]

    normalized = []
    seen = set()
    for tag in tags:
        value = tag.strip().lower()
        if value not in seen:
            seen.add(value)
            normalized.append(value)
    return normalized

def _legacy_address(record: dict[str, str]) -> str:
    """Read and normalize the email in a legacy contact record."""
    return record["email"].strip().lower()


def combine_contacts(
    primary: list[str],
    accounts: list[tuple[str, str]],
    legacy: list[dict[str, str]],
) -> list[str]:
    """Combine contacts from three supported import formats."""
    addresses = [address.strip().lower() for address in primary]
    for username, domain in accounts:
        address = username.strip() + "@" + domain.strip()
        addresses.append(address.lower())
    addresses.extend(map(_legacy_address, legacy))
    return addresses

def budget_shares(amounts: list[float]) -> list[float]:
    """Express each amount as a fraction of the total budget."""
    total = 0.0
    for amount in amounts:
        total += amount
    return list(amount / total for amount in amounts)

def _parse_status_code(token: str) -> int:
    """Parse a single decimal status code."""
    return int(token.strip(), 10)


def parse_status_codes(tokens: list[str]) -> list[int]:
    """Convert imported decimal status-code strings to integers."""
    return list(map(_parse_status_code, tokens))

def usable_readings(
    readings: list[int | float | None],
) -> list[int | float]:
    """Keep available, nonnegative sensor readings."""
    for reading in readings:
        if reading is not None and not isinstance(reading, (int, float)):
            raise TypeError("Readings must be numeric or missing")
    return list(filter(
        lambda value: value is not None and value >= 0,
        readings,
    ))

type MenuNode = str | list[MenuNode]


def _flatten_menu(node: MenuNode) -> list[str]:
    """Collect the leaf labels of one menu node."""
    if isinstance(node, str):
        return [node]
    if not node:
        return []
    return _flatten_menu(node[0]) + _flatten_menu(node[1:])


def menu_labels(menu: list[MenuNode]) -> list[str]:
    """Return the menu's labels in display order."""
    return _flatten_menu(menu)

def rotate_queue(items: list[str], steps: int) -> list[str]:
    """Move the next dispatch position to the start of a new queue."""
    if not items:
        return []
    shift = steps % len(items)
    return items[shift:] + items[:shift]

def email_domains(addresses: list[str]) -> list[str]:
    """List distinct normalized domains for a mailing-list report."""
    return sorted({
        address.rsplit("@", 1)[1].strip().lower()
        for address in addresses
    })

def latest_readings(
    records: list[tuple[str, float]],
) -> list[tuple[str, float]]:
    """Keep the latest reading for each sensor in first-seen order."""
    latest = {sensor: value for sensor, value in records}
    return list(latest.items())
